#!/usr/bin/env python3
"""Generates the operations, models and error table of the Relay Python SDK from the contract."""

from __future__ import annotations

import json
import keyword
import re
import sys
from pathlib import Path
from typing import Any

import yaml

GENERATOR_VERSION = "1"

HERE = Path(__file__).resolve()
SDK = HERE.parents[1]
REPO = HERE.parents[3]
CONTRACT = REPO / "contracts" / "openapi" / "server.yaml"
ERRORS = REPO / "contracts" / "errors.yaml"
OUT = SDK / "src" / "esuiss_relay" / "_generated"

HEADER = (
    "# Code generated by sdks/python/codegen/generate.py from contracts/openapi/server.yaml. DO NOT EDIT.\n"
)

HIDDEN_HEADERS = {
    "relay-version",
    "relay-beta",
    "idempotency-key",
    "dpop",
    "authorization",
    "relay-tenant",
    "relay-environment",
    "relay-csrf-token",
}
SKIPPED_TAGS = {"access", "messaging-inbound"}
BODY_TYPES = ("application/json", "application/merge-patch+json")
METHODS = ("get", "put", "post", "delete", "patch")
RESERVED = {
    "str",
    "int",
    "float",
    "bool",
    "list",
    "dict",
    "None",
    "m",
    "self",
    "body",
    "options",
    "idempotency_key",
    "_t",
}

BOOL = "tag:yaml.org,2002:bool"
TIMESTAMP = "tag:yaml.org,2002:timestamp"


class Loader(yaml.SafeLoader):
    pass


Loader.yaml_implicit_resolvers = {
    key: [(tag, regexp) for tag, regexp in resolvers if tag not in (BOOL, TIMESTAMP)]
    for key, resolvers in yaml.SafeLoader.yaml_implicit_resolvers.items()
}
Loader.add_implicit_resolver(BOOL, re.compile(r"^(?:true|false)$"), list("tf"))

_documents: dict[Path, Any] = {}


def load(path: Path) -> Any:
    path = path.resolve()
    if path not in _documents:
        with path.open(encoding="utf-8") as handle:
            _documents[path] = yaml.load(handle, Loader=Loader)  # noqa: S506
    return _documents[path]


def resolve(ref: str, base: Path) -> tuple[Path, str, Any]:
    file_part, _, pointer = ref.partition("#")
    path = (base.parent / file_part).resolve() if file_part else base.resolve()
    node = load(path)
    parts = [p.replace("~1", "/").replace("~0", "~") for p in pointer.split("/") if p]
    for part in parts:
        node = node[part]
    return path, "/".join(parts), node


def deref(node: Any, base: Path) -> tuple[Any, Path]:
    while isinstance(node, dict) and "$ref" in node:
        base, _, node = resolve(node["$ref"], base)
    return node, base


def pascal(text: str) -> str:
    parts = re.split(r"[^A-Za-z0-9]+", text)
    return "".join(p[:1].upper() + p[1:] for p in parts if p)


def snake(text: str) -> str:
    text = re.sub(r"[^A-Za-z0-9]+", "_", text)
    text = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", text)
    text = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", text)
    return text.strip("_").lower()


def ident(text: str) -> str:
    text = re.sub(r"[^A-Za-z0-9_]", "_", text)
    if not text or text[0].isdigit():
        text = "_" + text
    if keyword.iskeyword(text) or keyword.issoftkeyword(text) or text in RESERVED:
        text += "_"
    return text


def literal(value: Any) -> str:
    if value is None:
        return "None"
    if isinstance(value, bool):
        return "True" if value else "False"
    if isinstance(value, (int, float)):
        return repr(value)
    return json.dumps(value)


class Models:
    def __init__(self) -> None:
        self.names: dict[tuple[Path, str], str] = {}
        self.taken: set[str] = set()
        self.inline: dict[int, str] = {}
        self.order: list[tuple[str, Any, Path]] = []
        self.emitted: set[str] = set()
        self.queue: list[tuple[str, Any, Path]] = []
        self.keep: list[Any] = []

    def unique(self, wanted: str) -> str:
        name = ident(wanted)
        candidate = name
        index = 2
        while candidate in self.taken:
            candidate = f"{name}_{index}"
            index += 1
        self.taken.add(candidate)
        return candidate

    def register_named(self, path: Path) -> None:
        document = load(path)
        for key, node in document.items():
            self.names[(path.resolve(), key)] = self.unique(key)
            self.order.append((self.names[(path.resolve(), key)], node, path.resolve()))

    def ref_name(self, ref: str, base: Path) -> str | None:
        path, pointer, _node = resolve(ref, base)
        return self.names.get((path, pointer))

    def object_name(self, node: Any, base: Path, hint: str) -> str:
        key = id(node)
        if key not in self.inline:
            self.keep.append(node)
            self.inline[key] = self.unique(hint)
            self.queue.append((self.inline[key], node, base))
        return self.inline[key]

    def type_of(self, schema: Any, base: Path, hint: str, fmt: str) -> str:
        if schema is True or schema is None or schema == {}:
            return "_t.Any"
        if not isinstance(schema, dict):
            return "_t.Any"
        if "$ref" in schema:
            name = self.ref_name(schema["$ref"], base)
            if name is not None:
                return fmt.format(name)
            target, target_base = deref(schema, base)
            return self.type_of(target, target_base, hint, fmt)
        result = self.bare_type(schema, base, hint, fmt)
        if schema.get("nullable") is True and result != "_t.Any":
            return union([result, "None"])
        return result

    def bare_type(self, schema: dict[str, Any], base: Path, hint: str, fmt: str) -> str:
        if "const" in schema:
            return literal_type([schema["const"]])
        if "enum" in schema:
            return literal_type(schema["enum"])
        if schema.get("properties"):
            return fmt.format(self.object_name(schema, base, hint))
        if "allOf" in schema:
            members = schema["allOf"]
            if self.all_objects(members, base):
                return fmt.format(self.object_name(schema, base, hint))
            if len(members) == 1:
                return self.type_of(members[0], base, hint, fmt)
            return "_t.Any"
        for word in ("oneOf", "anyOf"):
            if word in schema:
                options = [
                    self.type_of(member, base, f"{hint}Option{index + 1}", fmt)
                    for index, member in enumerate(schema[word])
                ]
                return union(options)
        kind = schema.get("type")
        if isinstance(kind, list):
            return union([self.bare_type({**schema, "type": k}, base, hint, fmt) for k in kind])
        if kind == "string":
            return "str"
        if kind == "integer":
            return "int"
        if kind == "number":
            return "float"
        if kind == "boolean":
            return "bool"
        if kind == "null":
            return "None"
        if kind == "array":
            item = self.type_of(schema.get("items"), base, f"{hint}Item", fmt)
            return f"list[{item}]"
        if kind == "object":
            extra = schema.get("additionalProperties")
            if isinstance(extra, dict) and extra:
                return f"dict[str, {self.type_of(extra, base, f'{hint}Value', fmt)}]"
            return "dict[str, _t.Any]"
        return "_t.Any"

    def all_objects(self, members: list[Any], base: Path) -> bool:
        if not members:
            return False
        for member in members:
            target, target_base = deref(member, base)
            if not isinstance(target, dict):
                return False
            if "allOf" in target:
                if not self.all_objects(target["allOf"], target_base):
                    return False
            elif not (target.get("properties") or target.get("type") == "object"):
                return False
        return True

    def merged(self, schema: dict[str, Any], base: Path) -> tuple[dict[str, tuple[Any, Path]], set[str]]:
        props: dict[str, tuple[Any, Path]] = {}
        required: set[str] = set()
        for member in schema.get("allOf", []):
            target, target_base = deref(member, base)
            sub_props, sub_required = self.merged(target, target_base)
            props.update(sub_props)
            required |= sub_required
        for name, prop in (schema.get("properties") or {}).items():
            props[name] = (prop, base)
        required |= set(schema.get("required") or [])
        return props, required

    def is_object(self, node: Any, base: Path) -> bool:
        if not isinstance(node, dict):
            return False
        if node.get("properties"):
            return True
        return "allOf" in node and self.all_objects(node["allOf"], base)

    def typed_dict(self, name: str, node: dict[str, Any], base: Path) -> str:
        props, required = self.merged(node, base)
        lines = [f'{name} = _t.TypedDict(\n    "{name}",\n    {{']
        for prop, (schema, prop_base) in props.items():
            kind = self.type_of(schema, prop_base, f"{name}_{pascal(prop)}", '"{}"')
            if prop not in required:
                kind = f"_t.NotRequired[{kind}]"
            lines.append(f"        {json.dumps(prop)}: {kind},")
        lines.append("    },\n)")
        return "\n".join(lines)

    def prepare(self) -> None:
        for name, node, base in self.order:
            if self.is_object(node, base):
                self.inline[id(node)] = name

    def emit(self) -> str:
        blocks: list[str] = []
        for name, node, base in self.order:
            blocks.append(self.definition(name, node, base))
        while self.queue:
            name, node, base = self.queue.pop(0)
            if name in self.emitted:
                continue
            blocks.append(self.definition(name, node, base))
        return "\n\n\n".join(blocks)

    def definition(self, name: str, node: Any, base: Path) -> str:
        self.emitted.add(name)
        if self.is_object(node, base):
            return self.typed_dict(name, node, base)
        kind = self.type_of(node, base, name, '"{}"')
        return f"{name}: _t.TypeAlias = {kind}"


def literal_type(values: list[Any]) -> str:
    if any(isinstance(v, float) for v in values):
        return "float"
    if any(isinstance(v, (dict, list)) for v in values):
        return "_t.Any"
    present = [v for v in values if v is not None]
    parts = []
    if present:
        parts.append("_t.Literal[" + ", ".join(literal(v) for v in present) + "]")
    if len(present) != len(values):
        parts.append("None")
    return union(parts)


def union(options: list[str]) -> str:
    unique: list[str] = []
    for option in options:
        if option not in unique:
            unique.append(option)
    if "_t.Any" in unique:
        return "_t.Any"
    if len(unique) == 1:
        return unique[0]
    return "_t.Union[" + ", ".join(unique) + "]"


def selected(operation: dict[str, Any], path: str) -> bool:
    if path.startswith("/inbound/"):
        return False
    tags = operation.get("tags") or []
    if tags and tags[0] in SKIPPED_TAGS:
        return False
    security = operation.get("security")
    if security:
        return any("access_bearer" in requirement for requirement in security)
    return True


def success(operation: dict[str, Any], base: Path) -> tuple[str, Any, Path]:
    responses = operation.get("responses") or {}
    codes = [c for _s, c in sorted((str(c), c) for c in responses if str(c).startswith("2"))]
    for code in codes:
        response, response_base = deref(responses[code], base)
        content = (response or {}).get("content") or {}
        if "application/json" in content:
            return "json", content["application/json"].get("schema"), response_base
    for code in codes:
        response, response_base = deref(responses[code], base)
        content = (response or {}).get("content") or {}
        if content:
            return "text", None, response_base
    return "none", None, base


def paginated(models: Models, operation: dict[str, Any], base: Path, params: list[tuple[dict[str, Any], Path]]) -> Any:
    names = {p["name"] for p, _b in params if p.get("in") == "query"}
    if "starting_after" not in names:
        return None
    kind, schema, schema_base = success(operation, base)
    if kind != "json" or schema is None:
        return None
    target, target_base = deref(schema, schema_base)
    if not models.is_object(target, target_base):
        return None
    props, _required = models.merged(target, target_base)
    if not {"data", "has_more", "next_cursor"} <= props.keys():
        return None
    data, data_base = props["data"]
    data, data_base = deref(data, data_base)
    return data.get("items"), data_base


def operations(models: Models) -> str:
    spec = load(CONTRACT)
    methods: list[str] = []
    for path, item in spec["paths"].items():
        shared = item.get("parameters") or []
        for verb in METHODS:
            operation = item.get(verb)
            if not operation or not selected(operation, path):
                continue
            code = method(models, path, verb, operation, shared)
            if code:
                methods.append(code)
    body = "\n\n".join(methods)
    return (
        HEADER
        + '"""Relay API operations, one method per operation of the contract."""\n\n'
        + "from __future__ import annotations\n\n"
        + "import typing as _t\n\n"
        + "from .._base import OperationsBase, RequestOptions\n"
        + "from .._pagination import Page\n"
        + "from . import models as m\n\n\n"
        + "class Operations(OperationsBase):\n"
        + '    """The generated operations of the Relay server API."""\n\n'
        + body
        + "\n"
    )


def method(models: Models, path: str, verb: str, operation: dict[str, Any], shared: list[Any]) -> str | None:
    op_id = operation["operationId"]
    params: list[tuple[dict[str, Any], Path]] = []
    for raw in list(shared) + list(operation.get("parameters") or []):
        param, param_base = deref(raw, CONTRACT)
        params.append((param, param_base))
    idempotent = any(p["name"].lower() == "idempotency-key" for p, _b in params)

    body_type = None
    body_required = False
    content_type = None
    request = operation.get("requestBody")
    if request is not None:
        request, request_base = deref(request, CONTRACT)
        content = request.get("content") or {}
        content_type = next((c for c in BODY_TYPES if c in content), None)
        if content_type is None:
            return None
        body_required = bool(request.get("required"))
        body_type = models.type_of(
            content[content_type].get("schema"), request_base, pascal(op_id) + "Request", "m.{}"
        )

    used = {"self", "body", "options", "idempotency_key"}
    positional: list[tuple[int, str]] = []
    keywords: list[str] = []
    path_map: list[str] = []
    query_map: list[str] = []
    header_map: list[str] = []
    for param, param_base in params:
        location = param.get("in")
        name = param["name"]
        if location == "header" and name.lower() in HIDDEN_HEADERS:
            continue
        if location not in ("path", "query", "header"):
            continue
        py = ident(snake(name))
        while py in used:
            py += "_"
        used.add(py)
        kind = models.type_of(param.get("schema"), param_base, pascal(op_id) + pascal(name), "m.{}")
        if location == "path":
            positional.append((path.find("{" + name + "}"), f"{py}: {kind}"))
            path_map.append(f'"{name}": {py}')
            continue
        if param.get("required"):
            keywords.append(f"{py}: {kind}")
        else:
            keywords.append(f"{py}: {kind} | None = None")
        target = query_map if location == "query" else header_map
        target.append(f'"{name}": {py}')

    ordered = [text for _index, text in sorted(positional)]
    if body_type is not None:
        if body_required:
            ordered.append(f"body: {body_type}")
        else:
            keywords.insert(0, f"body: {body_type} | None = None")
    keywords = [k for k in keywords if " = " not in k] + [k for k in keywords if " = " in k]
    if idempotent:
        keywords.append("idempotency_key: str | None = None")
    keywords.append("options: RequestOptions | None = None")

    page = paginated(models, operation, CONTRACT, params)
    kind, schema, schema_base = success(operation, CONTRACT)
    if page is not None:
        item_schema, item_base = page
        item = models.type_of(item_schema, item_base, pascal(op_id) + "Item", "m.{}")
        returns = f"Page[{item}]"
    elif kind == "json":
        returns = models.type_of(schema, schema_base, pascal(op_id) + "Response", "m.{}")
    elif kind == "text":
        returns = "str"
    else:
        returns = "None"

    name = ident(snake(op_id))
    signature = ["self", *ordered]
    if keywords:
        signature.append("*")
        signature.extend(keywords)
    summary = (operation.get("summary") or op_id).strip().rstrip(".") + "."
    summary = summary.replace("\\", "\\\\").replace('"""', '\\"\\"\\"')
    args = [
        f'"{verb.upper()}"',
        json.dumps(path),
        "path={" + ", ".join(path_map) + "}",
        "query={" + ", ".join(query_map) + "}",
        "headers={" + ", ".join(header_map) + "}",
        f"body={'body' if body_type is not None else 'None'}",
        f"content_type={json.dumps(content_type) if content_type else 'None'}",
        f"idempotent={idempotent}",
        f"idempotency_key={'idempotency_key' if idempotent else 'None'}",
        "options=options",
    ]
    lines = [f"    def {name}(", *(f"        {part}," for part in signature), f"    ) -> {returns}:"]
    lines.append(f'        """{summary}"""')
    if page is not None:
        lines.append(f"        return _t.cast({json.dumps(returns)}, self._page(")
    elif returns == "None":
        lines.append("        self._call(")
    else:
        lines.append(f"        return _t.cast({json.dumps(returns)}, self._call(")
        args.append(f'response="{kind}"')
    if page is None and returns == "None":
        args.append('response="none"')
    lines.extend(f"            {arg}," for arg in args)
    lines.append("        ))" if returns != "None" else "        )")
    return "\n".join(lines)


def errors_table() -> str:
    document = load(ERRORS)
    rows = []
    for entry in document["codes"]:
        rows.append(
            f'    "{entry["code"]}": ErrorInfo("{entry["family"]}", {int(entry["status"])}, {bool(entry["retryable"])}),'
        )
    defaults = []
    for entry in document.get("retryable_defaults", []):
        code = json.dumps(entry["code"]) if entry.get("code") else "None"
        defaults.append(f"    ({int(entry['status'])}, {code}, {bool(entry['retryable'])}),")
    return (
        HEADER
        + '"""The error catalog of the contract: family, status and retryable of every code."""\n\n'
        + "from __future__ import annotations\n\n"
        + "import typing as _t\n\n\n"
        + "class ErrorInfo(_t.NamedTuple):\n"
        + '    """Family, HTTP status and retryable flag of an error code."""\n\n'
        + "    family: str\n    status: int\n    retryable: bool\n\n\n"
        + "ERRORS: dict[str, ErrorInfo] = {\n"
        + "\n".join(rows)
        + "\n}\n\n"
        + "RETRYABLE_DEFAULTS: tuple[tuple[int, str | None, bool], ...] = (\n"
        + "\n".join(defaults)
        + "\n)\n"
    )


def version_module() -> str:
    spec = load(CONTRACT)
    return (
        HEADER
        + '"""The API version this SDK is pinned to."""\n\n'
        + f'API_VERSION = "{spec["info"]["version"]}"\n'
        + f'GENERATOR_VERSION = "{GENERATOR_VERSION}"\n'
    )


def main() -> int:
    components = CONTRACT.parent / "components"
    models = Models()
    for file in ("schemas.yaml", "problem.yaml"):
        models.register_named(components / file)
    models.prepare()
    operations_code = operations(models)
    models_code = (
        HEADER
        + '"""Typed shapes of the request and response bodies of the Relay server API."""\n\n'
        + "from __future__ import annotations\n\n"
        + "import typing as _t\n\n\n"
        + models.emit()
        + "\n"
    )
    OUT.mkdir(parents=True, exist_ok=True)
    files = {
        "__init__.py": HEADER + '"""Code generated from the Relay contract."""\n',
        "models.py": models_code,
        "operations.py": operations_code,
        "errors.py": errors_table(),
        "version.py": version_module(),
    }
    for name, text in files.items():
        (OUT / name).write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
